#!/usr/bin/env python
"""Verify that ckpt/best.pt still aligns with the tokenizer regenerated by
stage2_tokenizer.py.

The checkpoint stores embeddings indexed by *merge rank* (id 256..4095), so it
is only meaningful if the BPE learned from the current corpus is the same one
used during pretraining. The published best.pt reached val_loss=5.8945 on
2023 tokens; a vocabulary mismatch pushes the loss up towards ln(4160)=8.33.

Usage:  python verify_ckpt.py [n_batches]
"""
import os
import sys
import time

import numpy as np
import torch

import stage3_pretrain as s3

N = int(sys.argv[1]) if len(sys.argv) > 1 else 15
BATCH = 64                      # same as pretraining eval
PUBLISHED = 5.8945              # val loss of ckpt/best.pt @ step 3000

t0 = time.time()


def log(m):
    print(f"[{time.time()-t0:7.1f}s] {m}", flush=True)


def main():
    ckpt = os.environ.get("CKPT") or os.path.join(
        os.path.dirname(os.path.abspath(__file__)), "ckpt", "best.pt")
    log(f"loading {ckpt}")
    model = s3.MarketGPT()
    sd = torch.load(ckpt, map_location="cpu", weights_only=True)
    model.load_state_dict(sd)
    model.eval()

    ds = s3.MarketLMSmart(split_years=[2023])
    dl = torch.utils.data.DataLoader(ds, batch_size=BATCH, shuffle=False,
                                     drop_last=True)
    tot = n = 0
    with torch.no_grad():
        for i, xb in enumerate(dl):
            if i >= N:
                break
            _, loss = model(xb, xb)
            tot += loss.item() * len(xb)
            n += len(xb)
            if i % 5 == 0:
                log(f"  batch {i}: loss={loss.item():.4f}")
    vl = tot / max(n, 1)
    verdict = "ALIGNED" if vl < 6.5 else "MISMATCH (regenerate ckpt with stage3)"
    log(f"val_loss={vl:.4f} (published {PUBLISHED}) over {n:,} windows "
        f"-> tokenizer/ckpt {verdict}")
    print(f"VERIFY {verdict}: val_loss={vl:.4f}", flush=True)


if __name__ == "__main__":
    main()
